SET LOCAL ROLE sim_guru_owner;
CREATE TABLE app.announcements(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 200),body text NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 5000),severity text NOT NULL CHECK(severity IN('info','success','warning','critical')),active boolean NOT NULL DEFAULT true,
 date_start date,date_end date,target_role text NOT NULL CHECK(target_role IN('all','guru','admin')),target_users uuid[] NOT NULL DEFAULT '{}',dismissible boolean NOT NULL DEFAULT true,allow_dismiss uuid[] NOT NULL DEFAULT '{}',deny_dismiss uuid[] NOT NULL DEFAULT '{}',cta_text text,cta_url text,send_email boolean NOT NULL DEFAULT false,reminder_offsets int[] NOT NULL DEFAULT '{}' CHECK(reminder_offsets<@ARRAY[1,2,3]),version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(date_end IS NULL OR date_start IS NULL OR date_end>=date_start),CHECK(NOT allow_dismiss && deny_dismiss),CHECK((cta_text IS NULL)=(cta_url IS NULL)),CHECK(cta_url IS NULL OR (cta_url~'^https?://' AND cta_url!~'[[:space:]@\\]')));
CREATE TABLE app.announcement_dismissals(announcement_id uuid NOT NULL REFERENCES app.announcements(id),user_id uuid NOT NULL REFERENCES app.app_users(id),version bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(announcement_id,user_id,version));
CREATE TABLE ops.domain_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dedupe_key text NOT NULL UNIQUE,recipient_id uuid NOT NULL REFERENCES app.app_users(id),assignment_id uuid REFERENCES app.activity_assignments(id),subject text NOT NULL CHECK(length(subject)<=300),body text NOT NULL CHECK(length(body)<=8000),state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','sending','sent','retry_wait','failed','unknown','cancelled')),attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp(),lease_token uuid,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz);
CREATE INDEX domain_outbox_ready ON ops.domain_outbox(next_attempt_at) WHERE state IN('pending','retry_wait','sending');
CREATE TABLE ops.job_runs(business_key text PRIMARY KEY,kind text NOT NULL,state text NOT NULL CHECK(state IN('pending','running','completed','failed','paused')),attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp(),result jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['app.announcements','app.announcement_dismissals','ops.domain_outbox','ops.job_runs'] LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY owner_internal ON %s TO sim_guru_owner USING(true) WITH CHECK(true)',t);END LOOP;END $$;
INSERT INTO app.system_settings(key,typed_value) VALUES('operations.config','{"mailEnabled":false,"securityMailEnabled":false,"jobsEnabled":false,"maintenance":false,"maintenanceStart":null,"maintenanceEnd":null}'::jsonb);
CREATE OR REPLACE FUNCTION auth_private.maintenance_enabled() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT coalesce((SELECT typed_value='true'::jsonb FROM app.system_settings WHERE key='maintenance.enabled'),false) OR coalesce((SELECT (typed_value->>'maintenance')::boolean OR ((typed_value->>'maintenanceStart')::timestamptz<=transaction_timestamp() AND (typed_value->>'maintenanceEnd')::timestamptz>transaction_timestamp()) FROM app.system_settings WHERE key='operations.config'),false) $$;
CREATE FUNCTION app.announcement_visible(a app.announcements,u uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT a.active AND (a.date_start IS NULL OR a.date_start<=app.activity_today()) AND (a.date_end IS NULL OR a.date_end>=app.activity_today()) AND (CASE WHEN cardinality(a.target_users)>0 THEN u=ANY(a.target_users) ELSE a.target_role='all' OR EXISTS(SELECT 1 FROM app.app_users WHERE id=u AND role=a.target_role) END) $$;
CREATE FUNCTION app.operations_read(p_session text,p_kind text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid; res jsonb;BEGIN
 actor:=app.activity_guard(p_session,false);
 IF p_kind='announcements' THEN SELECT coalesce(jsonb_agg((to_jsonb(a)-ARRAY['target_users','target_role','allow_dismiss','deny_dismiss','send_email'])||jsonb_build_object('canDismiss',app.actor_is_admin() OR (CASE WHEN actor=ANY(a.deny_dismiss) THEN false WHEN actor=ANY(a.allow_dismiss) THEN true ELSE a.dismissible END)) ORDER BY CASE severity WHEN 'critical' THEN 0 WHEN 'warning' THEN 1 WHEN 'success' THEN 2 ELSE 3 END,updated_at DESC),'[]'::jsonb) INTO res FROM app.announcements a WHERE app.announcement_visible(a,actor) AND NOT EXISTS(SELECT 1 FROM app.announcement_dismissals d WHERE d.announcement_id=a.id AND d.user_id=actor AND d.version=a.version);RETURN res;
 END IF;
 PERFORM auth_private.require_admin();
 IF p_kind='manage' THEN RETURN (SELECT coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('recipientNames',(SELECT coalesce(jsonb_object_agg(u.id,u.full_name),'{}'::jsonb) FROM app.app_users u WHERE u.id=ANY(a.target_users||a.allow_dismiss||a.deny_dismiss))) ORDER BY updated_at DESC),'[]'::jsonb) FROM app.announcements a);
 ELSIF p_kind='operations' THEN RETURN jsonb_build_object('config',(SELECT jsonb_build_object('value',typed_value,'version',version::text) FROM app.system_settings WHERE key='operations.config'),'maintenanceActive',auth_private.maintenance_enabled(),'lastWorkerAt',(SELECT max(used_at) FROM ops.worker_tickets),'outbox',(SELECT coalesce(jsonb_agg(x),'[]'::jsonb) FROM(SELECT id,state,attempts,next_attempt_at,created_at FROM ops.domain_outbox ORDER BY created_at DESC LIMIT 100)x),'jobs',(SELECT coalesce(jsonb_agg(x),'[]'::jsonb) FROM(SELECT * FROM ops.job_runs ORDER BY created_at DESC LIMIT 100)x));END IF;
 RAISE EXCEPTION 'INVALID_OPERATION' USING ERRCODE='22023';END $$;
CREATE FUNCTION app.operations_command(p_session text,p_kind text,d jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid; a app.announcements%ROWTYPE; rid uuid; v bigint;BEGIN
 actor:=app.activity_guard(p_session,true);
 IF p_kind='dismiss' THEN SELECT * INTO a FROM app.announcements WHERE id=(d->>'id')::uuid FOR UPDATE;IF a.id IS NULL OR NOT app.announcement_visible(a,actor) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;IF a.version<>(d->>'version')::bigint THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;IF NOT(app.actor_is_admin() OR CASE WHEN actor=ANY(a.deny_dismiss) THEN false WHEN actor=ANY(a.allow_dismiss) THEN true ELSE a.dismissible END) THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';END IF;INSERT INTO app.announcement_dismissals VALUES(a.id,actor,a.version,clock_timestamp()) ON CONFLICT DO NOTHING;RETURN '{}'::jsonb;END IF;
 PERFORM auth_private.require_admin();
 IF length(btrim(coalesce(d->>'reason',''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'INVALID_REASON' USING ERRCODE='22023';END IF;
 IF p_kind='save' THEN
 IF d->>'id' IS NULL THEN INSERT INTO app.announcements(title,body,severity,target_role) VALUES(d->>'title',d->>'body',d->>'severity',d->>'targetRole') RETURNING id INTO rid;ELSE rid:=(d->>'id')::uuid;SELECT * INTO a FROM app.announcements WHERE id=rid FOR UPDATE;IF a.id IS NULL OR a.version<>(d->>'version')::bigint THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;END IF;
 UPDATE app.announcements SET title=d->>'title',body=d->>'body',severity=d->>'severity',active=(d->>'active')::boolean,date_start=(d->>'from')::date,date_end=(d->>'to')::date,target_role=d->>'targetRole',target_users=ARRAY(SELECT jsonb_array_elements_text(d->'targetUsers')::uuid),dismissible=(d->>'dismissible')::boolean,allow_dismiss=ARRAY(SELECT jsonb_array_elements_text(d->'allowDismiss')::uuid),deny_dismiss=ARRAY(SELECT jsonb_array_elements_text(d->'denyDismiss')::uuid),cta_text=d->>'ctaText',cta_url=d->>'ctaUrl',send_email=(d->>'sendEmail')::boolean,reminder_offsets=ARRAY(SELECT jsonb_array_elements_text(d->'reminderOffsets')::int),version=CASE WHEN a.id IS NULL THEN 1 ELSE version+1 END,updated_at=clock_timestamp() WHERE id=rid RETURNING version INTO v;
 UPDATE ops.domain_outbox SET state='cancelled' WHERE dedupe_key LIKE 'announcement:'||rid||':%' AND state IN('pending','retry_wait');
 ELSIF p_kind='deactivate' THEN UPDATE app.announcements SET active=false,version=version+1,updated_at=clock_timestamp() WHERE id=(d->>'id')::uuid AND version=(d->>'version')::bigint RETURNING id INTO rid;IF rid IS NULL THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;UPDATE ops.domain_outbox SET state='cancelled' WHERE dedupe_key LIKE 'announcement:'||rid||':%' AND state IN('pending','retry_wait');
 ELSIF p_kind='settings' THEN UPDATE app.system_settings SET typed_value=d->'config',version=version+1,updated_by=actor,updated_at=clock_timestamp() WHERE key='operations.config' AND version=(d->>'version')::bigint RETURNING version INTO v;IF v IS NULL THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;
 ELSIF p_kind='job-retry' THEN UPDATE ops.job_runs SET attempts=0,next_attempt_at=clock_timestamp() WHERE business_key=d->>'key' AND state='failed';IF NOT FOUND THEN RAISE EXCEPTION 'RETRY_NOT_ALLOWED' USING ERRCODE='42501';END IF;
 ELSIF p_kind='retry' THEN UPDATE ops.domain_outbox SET state='pending',attempts=0,next_attempt_at=clock_timestamp(),lease_token=null,lease_until=null WHERE id=(d->>'id')::uuid AND state='failed' RETURNING id INTO rid;IF rid IS NULL THEN RAISE EXCEPTION 'RETRY_NOT_ALLOWED' USING ERRCODE='42501';END IF;
 ELSIF p_kind='reconcile' THEN UPDATE ops.domain_outbox SET state=CASE WHEN (d->>'sent')::boolean THEN 'sent' ELSE 'cancelled' END,completed_at=clock_timestamp(),lease_token=null,lease_until=null WHERE id=(d->>'id')::uuid AND state='unknown' RETURNING id INTO rid;IF rid IS NULL THEN RAISE EXCEPTION 'RECONCILE_NOT_ALLOWED' USING ERRCODE='42501';END IF;
 ELSE RAISE EXCEPTION 'INVALID_OPERATION' USING ERRCODE='22023';END IF;
 INSERT INTO ops.audit_logs(actor_id,action,entity_id,reason,redacted_changes) VALUES(actor,'operations.'||p_kind,rid,d->>'reason',jsonb_build_object('version',v,'jobKey',d->>'key','config',d->'config'));RETURN jsonb_build_object('id',rid,'version',v::text);END $$;
CREATE FUNCTION ops.domain_claim() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE o ops.domain_outbox%ROWTYPE;em text;BEGIN
 IF auth_private.maintenance_enabled() OR NOT coalesce((SELECT (typed_value->>'mailEnabled')::boolean FROM app.system_settings WHERE key='operations.config'),false) THEN RETURN null;END IF;
 -- An expired SMTP lease has an ambiguous receipt; never resend blindly.
 UPDATE ops.domain_outbox SET state='unknown',lease_token=null,lease_until=null WHERE state='sending' AND lease_until<clock_timestamp();
 UPDATE ops.domain_outbox SET state='cancelled' WHERE state IN('pending','retry_wait') AND assignment_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM app.activity_assignments a WHERE a.id=ops.domain_outbox.assignment_id AND a.effective_user_id=ops.domain_outbox.recipient_id);
 UPDATE ops.domain_outbox pending SET state='cancelled' WHERE state IN('pending','retry_wait') AND NOT EXISTS(SELECT 1 FROM app.app_users u WHERE u.id=pending.recipient_id AND u.status='active' AND u.email_verified_at IS NOT NULL);
 SELECT * INTO o FROM ops.domain_outbox WHERE state IN('pending','retry_wait') AND attempts<5 AND next_attempt_at<=clock_timestamp() ORDER BY next_attempt_at,id FOR UPDATE SKIP LOCKED LIMIT 1;IF o.id IS NULL THEN RETURN null;END IF;
 SELECT contact_email INTO em FROM app.app_users WHERE id=o.recipient_id;
 UPDATE ops.domain_outbox SET state='sending',attempts=attempts+1,lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '2 minutes' WHERE id=o.id RETURNING * INTO o;
 RETURN jsonb_build_object('id',o.id,'lease',o.lease_token,'to',em,'subject',o.subject,'text',o.body);END $$;
CREATE FUNCTION ops.domain_finish(p_id uuid,p_lease uuid,p_result text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE n int;BEGIN
 IF p_result NOT IN('sent','retry_wait','failed','unknown') THEN RAISE EXCEPTION 'INVALID_RESULT';END IF;
 UPDATE ops.domain_outbox SET state=CASE WHEN p_result='retry_wait' AND attempts>=5 THEN 'failed' ELSE p_result END,next_attempt_at=clock_timestamp()+make_interval(secs=>CASE attempts WHEN 1 THEN 60 WHEN 2 THEN 300 WHEN 3 THEN 900 ELSE 3600 END+floor(random()*20)::int),lease_token=null,lease_until=null,completed_at=CASE WHEN p_result IN('sent','failed') THEN clock_timestamp() ELSE null END WHERE id=p_id AND state='sending' AND lease_token=p_lease AND lease_until>clock_timestamp();GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END $$;
CREATE FUNCTION ops.enqueue_announcements() RETURNS int LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE n int;BEGIN
 INSERT INTO ops.domain_outbox(dedupe_key,recipient_id,subject,body) SELECT 'announcement:'||a.id||':'||a.version||':'||u.id||':'||CASE WHEN a.date_end-app.activity_today()=ANY(a.reminder_offsets) THEN (a.date_end-app.activity_today())::text ELSE 'initial' END,u.id,a.title,a.body||CASE WHEN a.cta_url IS NULL THEN '' ELSE E'\n\n'||a.cta_text||': '||a.cta_url END FROM app.announcements a CROSS JOIN app.app_users u WHERE u.status='active' AND u.email_verified_at IS NOT NULL AND a.send_email AND app.announcement_visible(a,u.id) ON CONFLICT(dedupe_key) DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;RETURN n;END $$;
CREATE FUNCTION ops.run_jobs() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE n int:=0;f int:=0;BEGIN
 PERFORM pg_advisory_xact_lock(734190,1);
 IF auth_private.maintenance_enabled() OR NOT coalesce((SELECT (typed_value->>'jobsEnabled')::boolean FROM app.system_settings WHERE key='operations.config'),false) THEN RETURN jsonb_build_object('paused',true);END IF;
 PERFORM ops.scheduled_finance();PERFORM ops.reminders();IF (clock_timestamp() AT TIME ZONE 'Asia/Jakarta')::time>='08:00' THEN n:=ops.enqueue_announcements();END IF;
 INSERT INTO ops.domain_outbox(dedupe_key,recipient_id,subject,body) SELECT f.dedupe_key,f.recipient_id,'Slip honorarium tersedia','Slip honorarium atau koreksi telah tersedia. Buka menu Honorarium pada SIM GURU.' FROM finance.notification_outbox f WHERE f.state='pending' ON CONFLICT(dedupe_key) DO NOTHING;GET DIAGNOSTICS f=ROW_COUNT;
 INSERT INTO ops.job_runs(business_key,kind,state,attempts,result,completed_at) VALUES('notifications:'||app.activity_today(),'notifications','completed',1,jsonb_build_object('announcements',n,'honor',f),clock_timestamp()) ON CONFLICT(business_key) DO UPDATE SET attempts=ops.job_runs.attempts+1,result=excluded.result,completed_at=excluded.completed_at;
 RETURN jsonb_build_object('announcements',n,'honor',f);END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA ops FROM PUBLIC;
REVOKE ALL ON FUNCTION app.announcement_visible(app.announcements,uuid),app.operations_read(text,text),app.operations_command(text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.operations_read(text,text),app.operations_command(text,text,jsonb) TO sim_guru_business;
GRANT USAGE ON SCHEMA ops TO sim_guru_worker;
GRANT EXECUTE ON FUNCTION ops.domain_claim(),ops.domain_finish(uuid,uuid,text),ops.run_jobs() TO sim_guru_worker;
RESET ROLE;

